}

Method.Source:
/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <returns>NDXDayTimeString</returns>
display NDXDayTimeString Duration()
{
    ;
    if(this.Ende > DateTimeUtil::minValue() && this.Start > DateTimeUtil::minValue())
    {
        return NDXHelperCommon::seconds2Str(DateTimeUtil::getDifference(this.Ende ? this.Ende : DateTimeUtil::utcNow(), this.Start));
    }

    return '';

}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "DS_Count">int</param>
/// <param name = "DS_new">int</param>
/// <param name = "DS_changed">int</param>
/// <param name = "lThread">boolean</param>
/// <returns>NDXJobManagerJobs</returns>
NDXJobManagerJobs ende(int DS_Count, int DS_new, int DS_changed,
                    boolean lThread = true)                        
{
    ;

    if (this.isDeactivated == NoYes::Yes)
    {
        return this;
    }

    this.Ende       = DateTimeUtil::utcNow();
    this.isRunning  = NoYes::No;
    this.setCountValues(DS_Count, DS_New, DS_changed);

    new ExecutePermission().assert();
    NDXJobMangerJobsClass::ThreadExecute_Update(this);

    return NDXJobManagerJobs::findByRecId(this.RecId);
}

/// <summary>
/// DebuC 27.02.24
/// </summary>
/// <param name = "_recId">RefRecId</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXJobManagerJobs</returns>
static NDXJobManagerJobs findByRecId(RefRecId _recId, boolean _forUpdate = false)
{
    NDXJobManagerJobs jobManagerJobs;

    jobManagerJobs.selectForUpdate(_forUpdate);

    select firstonly jobManagerJobs
        where jobManagerJobs.RecId == _recId;

    return jobManagerJobs;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "lThread">boolean</param>
void initialize(boolean lThread = true)
{
    ;

    this.Start      = utcDateTimeNull();
    this.Ende       = utcDateTimeNull();
    this.Aktion     = '';
    this.Counter    = 0;
    this.Kennung    = '';
    this.DScount   = 0;
    this.DSchange  = 0;
    this.DSnew     = 0;
    this.isRunning  = NoYes::No;

    new ExecutePermission().assert();

    NDXJobMangerJobsClass::ThreadExecute_Update(this);   
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
public void initValue()
{
    super();

    this.Blocked = NoYes::No;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "action">str</param>
/// <param name = "kennung">str</param>
/// <param name = "DS_Count">int</param>
/// <param name = "DS_new">int</param>
/// <param name = "DS_changed">int</param>
/// <param name = "lThread">boolean</param>
/// <returns>NDXJobManagerJobs</returns>
NDXJobManagerJobs setAction(str action, str kennung,
                         int DS_Count, int DS_new, int DS_changed,
                         boolean lThread = true)
{
    ;
    if (this.isDeactivated == NoYes::Yes)
    {
        return this;
    }

    this.Aktion     = action;
    this.Kennung    = kennung;
    this.Counter    = this.Counter + 1;
    this.setCountValues(DS_Count, DS_New, DS_changed);

    NDXJobMangerJobsClass::ThreadExecute_Update(this);

    return NDXJobManagerJobs::findByRecId(this.RecId);
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "DS_Count">int</param>
/// <param name = "DS_new">int</param>
/// <param name = "DS_changed">int</param>
void setCountValues(int DS_Count = NDXJobManagerJobsConstants::defaultInt, int DS_new = NDXJobManagerJobsConstants::defaultInt, int DS_changed = NDXJobManagerJobsConstants::defaultInt)
{

    if (DS_Count != NDXJobManagerJobsConstants::defaultInt)
    {
        this.DScount   = DS_Count;
    }
    if (DS_new != NDXJobManagerJobsConstants::defaultInt)
    {
        this.DSnew     = DS_new;
    }
    if (DS_changed != NDXJobManagerJobsConstants::defaultInt)
    {
        this.DSchange  = DS_changed;
    }
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "action">str</param>
/// <param name = "kennung">str</param>
/// <param name = "lThread">boolean</param>
/// <returns>NDXJobManagerJobs</returns>
NDXJobManagerJobs start(str action = '',
                     str kennung = '',
                     boolean lThread = true)

{
    xSession    xSession;
    ;

    if (this.isDeactivated == NoYes::Yes)
    {
        return this;
    }

    xSession            = new xSession();
    this.isRunning      = NoYes::Yes;
    this.Start          = DateTimeUtil::utcNow();
    this.UK             = curext();
    this.Aktion         = action;
    this.Kennung        = kennung;

    this.SessionID      = xSession::numSession();
    this.DatabaseSpId   = xSession.databaseSpid();
    this.AOSName        = xSession.AOSName();

    NDXJobMangerJobsClass::ThreadExecute_Update(this);

    return NDXJobManagerJobs::findByRecId(this.RecId);
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <returns>boolean</returns>
public boolean validateDelete()
{
    boolean ret = true;

    if (this.isRunning == NoYes::Yes)
    {
        ret = checkFailed(strfmt("@NDX:NDXActiveEntryMustNotBeDeleted", this.JobManagerJobId, this.Start));    // Eintrag [%1] mit Startdatum [%2] ist aktiv und darf nicht gelöscht werden!
    }
    else if (this.Blocked == NoYes::Yes)
    {
        ret = checkFailed(strfmt("@NDX:NDXLockedEntryMustNotBeDeleted", this.JobManagerJobId, this.Start));    // Eintrag [%1] mit Startdatum [%2] ist gesperrt und darf nicht gelöscht werden!
    }
    if (ret)
    {
        ret = super();
    }

    return ret;
}

/// <summary>
/// Debu 22.09.23
/// </summary>
/// <param name = "jobId">NDXJobManagerJobId</param>
/// <param name = "initialize">boolean</param>
/// <returns>NDXJobManagerJobs</returns>
static server NDXJobManagerJobs find(NDXJobManagerJobId jobId
                                 ,boolean             initialize = true)
{
    NDXJobManagerJobs  cursor;
    ;

    cursor.selectForUpdate(true);
    select cursor where cursor.JobManagerJobId == jobId
    && cursor.Blocked ==  NoYes::No;

    if (!cursor)
    {
        cursor.JobManagerJobId = jobId;
        cursor = NDXJobMangerJobsClass::ThreadExecute_Insert(cursor);
    }
    else if (initialize)
    {
        cursor.initialize();
    }
    return cursor;
}
